  "welcome.eyebrow": "ಸ್ವಾಗತ",
  "welcome.heading": "Luminous StockHaven ಗೆ ಸ್ವಾಗತ",
  "welcome.subheading": "ನಿಮ್ಮ ದಾಸ್ತಾನನ್ನು ನಿಮ್ಮ ರೀತಿಯಲ್ಲಿ ನಿರ್ವಹಿಸಿ.",
  "welcome.intro": "ನಿಮಗೆ ಸರಳ ಮೊಬೈಲ್ ದಾಸ್ತಾನು ಸಹಾಯಕ ಬೇಕೇ ಅಥವಾ ನಿಮ್ಮ ಬೆಳೆಯುತ್ತಿರುವ ವ್ಯವಹಾರಕ್ಕಾಗಿ ಸಂಪೂರ್ಣ ದಾಸ್ತಾನು-ನಿರ್ವಹಣಾ ವ್ಯವಸ್ಥೆ ಬೇಕೇ, Luminous StockHaven ನಲ್ಲಿ ನಿಮಗಾಗಿ ಆಯ್ಕೆಗಳಿವೆ.",
  "welcome.explorePlans": "ನಿಮ್ಮ ಉಚಿತ ಪರೀಕ್ಷೆಯನ್ನು ಪ್ರಾರಂಭಿಸುವ ಮೊದಲು ನಮ್ಮ ಲಭ್ಯವಿರುವ ಯೋಜನೆಗಳನ್ನು ಅನ್ವೇಷಿಸಿ.",
  "welcome.seeIncluded": "ಏನು ಒಳಗೊಂಡಿದೆ ಎಂದು ನೋಡಿ",
  "welcome.choosePlan": "ಚಂದಾದಾರಿಕೆ ಯೋಜನೆಯನ್ನು ಆರಿಸಿ",
  "welcome.noTrialNote": "ಈ ಪರದೆಯನ್ನು ತೆರೆಯುವುದರಿಂದ ಏನೂ ಪ್ರಾರಂಭವಾಗುವುದಿಲ್ಲ. ಯಾವುದೇ ಪರೀಕ್ಷೆ ಪ್ರಾರಂಭವಾಗುವುದಿಲ್ಲ ಮತ್ತು ಯಾವುದೇ ಕಾರ್ಡ್‌ಗೆ ಶುಲ್ಕ ವಿಧಿಸಲಾಗುವುದಿಲ್ಲ — ನೀವು ಯೋಜನೆಯನ್ನು ಆರಿಸಿ ಅದನ್ನು ದೃಢೀಕರಿಸಿದಾಗ ಮಾತ್ರ ಏಳು ದಿನಗಳ ಪರೀಕ್ಷೆ ಪ್ರಾರಂಭವಾಗುತ್ತದೆ. ಎರಡೂ ವೆಬ್‌ಸೈಟ್ ಯೋಜನೆಗಳು ಮೊಬೈಲ್ ಸಹಾಯಕವನ್ನು ಒಳಗೊಂಡಿರುತ್ತವೆ, ಆದ್ದರಿಂದ ನೀವು ಅವುಗಳ ಮೇಲೆ ಮಾಸಿಕ ಮೊಬೈಲ್ ಶುಲ್ಕವನ್ನು ಎಂದಿಗೂ ಪಾವತಿಸುವುದಿಲ್ಲ.",
  "welcome.alreadyHaveAccount": "ಈಗಾಗಲೇ StockHaven ಖಾತೆ ಇದೆಯೇ?",
  "welcome.signIn": "ಸೈನ್ ಇನ್",
  "welcome.inventoryWaiting": "ಮತ್ತು ನಿಮ್ಮ ದಾಸ್ತಾನು ನೀವು ಬಿಟ್ಟ ಸ್ಥಳದಲ್ಲಿಯೇ ಇದೆ.",
  "thankYou.unverified.notVerified": "Stripe ಇನ್ನೂ ಈ ಚೆಕ್‌ಔಟ್ ಅನ್ನು ಹೊಂದಿಸುವುದನ್ನು ಪೂರ್ಣಗೊಳಿಸಿಲ್ಲ. ನಿಮ್ಮ ಪಾವತಿ ಸುರಕ್ಷಿತವಾಗಿದೆ — ಯಾವುದಕ್ಕೂ ಎರಡು ಬಾರಿ ಶುಲ್ಕ ವಿಧಿಸಲಾಗಿಲ್ಲ. ನಾವು ಪರಿಶೀಲಿಸುತ್ತಲೇ ಇರುತ್ತೇವೆ.",
  "thankYou.unverified.trialNotEligible": "ಈ ಇಮೇಲ್ ಈಗಾಗಲೇ ತನ್ನ ಒಂದು ಉಚಿತ ಪರೀಕ್ಷೆಯನ್ನು ಬಳಸಿದೆ, ಆದ್ದರಿಂದ ಪರೀಕ್ಷೆಯನ್ನು ಪ್ರಾರಂಭಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಇದು ತಪ್ಪು ಎಂದು ನೀವು ಭಾವಿಸಿದರೆ ಬೆಂಬಲವನ್ನು ಸಂಪರ್ಕಿಸಿ.",
  "thankYou.unverified.noPendingCheckout": "ಈ ಕಾರ್ಯಕ್ಷೇತ್ರಕ್ಕಾಗಿ ಬಾಕಿಯಿರುವ ಚೆಕ್‌ಔಟ್ ಅನ್ನು ನಾವು ಕಂಡುಹಿಡಿಯಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.",
  "thankYou.unverified.default": "ನಿಮ್ಮ ಖರೀದಿಯನ್ನು ಇನ್ನೂ ಪರಿಶೀಲಿಸಲಾಗಿಲ್ಲ. ನಾವು ಪರಿಶೀಲಿಸುತ್ತಲೇ ಇರುತ್ತೇವೆ — ಮತ್ತೊಂದು ಚೆಕ್‌ಔಟ್ ಪ್ರಾರಂಭಿಸಬೇಡಿ.",
  "thankYou.grantedTitle": "ನೀವು ಒಳಗಿದ್ದೀರಿ — ನಿಮ್ಮ ಯೋಜನೆಗೆ ಸ್ವಾಗತ.",
  "thankYou.trialRunning": "ನಿಮ್ಮ 7 ದಿನಗಳ ಉಚಿತ ಪರೀಕ್ಷೆ {date} ವರೆಗೆ ನಡೆಯುತ್ತಿದೆ. ಪರೀಕ್ಷೆ ಮುಗಿಯುವವರೆಗೆ ನಿಮಗೆ ಶುಲ್ಕ ವಿಧಿಸಲಾಗುವುದಿಲ್ಲ.",
  "thankYou.trialRunningNoDate": "ನಿಮ್ಮ 7 ದಿನಗಳ ಉಚಿತ ಪರೀಕ್ಷೆ ನಡೆಯುತ್ತಿದೆ. ಪರೀಕ್ಷೆ ಮುಗಿಯುವವರೆಗೆ ನಿಮಗೆ ಶುಲ್ಕ ವಿಧಿಸಲಾಗುವುದಿಲ್ಲ.",
  "thankYou.subscriptionActive": "ನಿಮ್ಮ ಚಂದಾದಾರಿಕೆ ಸಕ್ರಿಯವಾಗಿದೆ. ನೀವು ಈಗ ಅಪ್ಲಿಕೇಶನ್ ಬಳಸಲು ಪ್ರಾರಂಭಿಸಬಹುದು.",
  "thankYou.openPlan": "ನಿಮ್ಮ ಯೋಜನೆಯನ್ನು ತೆರೆಯಿರಿ",
  "thankYou.noSessionTitle": "ಇಲ್ಲಿ ಪರಿಶೀಲಿಸಲು ಯಾವುದೇ ಚೆಕ್‌ಔಟ್ ಇಲ್ಲ.",
  "thankYou.noSessionBody": "ಈ ಪುಟವು Stripe ಚೆಕ್‌ಔಟ್ ಅನ್ನು ದೃಢೀಕರಿಸುತ್ತದೆ. ನೀವು ಚಂದಾದಾರರಾಗುತ್ತಿದ್ದರೆ, ಯೋಜನೆಗಳ ಪುಟದಿಂದ ಪ್ರಾರಂಭಿಸಿ — ಯಾವುದಕ್ಕೂ ಶುಲ್ಕ ವಿಧಿಸಲಾಗಿಲ್ಲ.",
  "thankYou.backToPlans": "ಯೋಜನೆಗಳಿಗೆ ಹಿಂತಿರುಗಿ",
  "thankYou.checkingTitle": "ನಿಮ್ಮನ್ನು ನಿಮ್ಮ ಯೋಜನೆಗೆ ಕರೆದೊಯ್ಯಲಾಗುತ್ತಿದೆ…",
  "thankYou.pendingTitle": "ನಿಮ್ಮ ಖರೀದಿಯನ್ನು ಇನ್ನೂ ಪರಿಶೀಲಿಸಲಾಗಿಲ್ಲ.",
  "thankYou.checkingBody": "ನಾವು Stripe ನೊಂದಿಗೆ ನಿಮ್ಮ ಚಂದಾದಾರಿಕೆಯನ್ನು ದೃಢೀಕರಿಸುತ್ತಿದ್ದೇವೆ. ಇದು ಸಾಮಾನ್ಯವಾಗಿ ಕೆಲವು ಸೆಕೆಂಡುಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳುತ್ತದೆ — ದಯವಿಟ್ಟು ಈ ಪುಟವನ್ನು ತೆರೆದಿಡಿ.",
  "thankYou.serverVerified": "ನಿಮ್ಮ ಯೋಜನೆಯನ್ನು ಸರ್ವರ್-ಪರಿಶೀಲಿಸಿದ ಪೂರೈಕೆದಾರರ ದಾಖಲೆಗಳಿಂದ ನಿರ್ಧರಿಸಲಾಗುತ್ತದೆ. ಖರೀದಿಯನ್ನು ಪರಿಶೀಲಿಸುವವರೆಗೆ ಅಪ್ಲಿಕೇಶನ್ ಅನ್‌ಲಾಕ್ ಆಗುವುದಿಲ್ಲ.",
  "thankYou.checkAgain": "ಮತ್ತೆ ಪರಿಶೀಲಿಸಿ",
  "thankYou.doNotRetry": "ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಲು ಮತ್ತೊಂದು ಚೆಕ್‌ಔಟ್ ಪ್ರಾರಂಭಿಸಬೇಡಿ — ಅದು ಎರಡನೇ ಚಂದಾದಾರಿಕೆಯನ್ನು ರಚಿಸುತ್ತದೆ.",
  "subscribe.backToPlans": "ಯೋಜನೆಗಳಿಗೆ ಹಿಂತಿರುಗಿ",
  "subscribe.eyebrow": "ಚಂದಾದಾರಿಕೆ",
