  "subscribe.invalidBody": "ನೀವು ಅನುಸರಿಸಿದ ಲಿಂಕ್ ನಾವು ನೀಡುವ ಯೋಜನೆಯನ್ನು ಹೆಸರಿಸುವುದಿಲ್ಲ. ಮುಂದುವರಿಸಲು ಕೆಳಗಿನಿಂದ ಒಂದನ್ನು ಆರಿಸಿ — ಯಾವುದಕ್ಕೂ ಚಂದಾದಾರರಾಗಿಲ್ಲ.",
