  "subscribe.createAccountFirst": "ಮೊದಲು, ನಿಮ್ಮ ಇಮೇಲ್ ಮತ್ತು ಪಾಸ್‌ವರ್ಡ್‌ನೊಂದಿಗೆ ನಿಮ್ಮ ಖಾತೆಯನ್ನು ರಚಿಸಿ. ಚಂದಾದಾರಿಕೆಯನ್ನು ಪೂರ್ಣಗೊಳಿಸಲು ನೀವು ನೇರವಾಗಿ ಇಲ್ಲಿಗೆ ಹಿಂತಿರುಗುತ್ತೀರಿ.",
