  "subscribe.pastDue": "ನಿಮ್ಮ ಪಾವತಿ ಬಾಕಿಯಾಗಿದೆ. ಯೋಜನೆ ಆಯ್ಕೆಗಳ ಪುಟದಿಂದ ನಿಮ್ಮ ಪಾವತಿ ವಿಧಾನವನ್ನು ನೀವು ನವೀಕರಿಸಬಹುದು.",
