  "subscribe.noWorkspace": "ಈ ಖಾತೆಯಲ್ಲಿ ಇನ್ನೂ ಯಾವುದೇ ಕಾರ್ಯಕ್ಷೇತ್ರ ಲಭ್ಯವಿಲ್ಲ. ಸಹಾಯಕ್ಕಾಗಿ Luminous StockHaven ಬೆಂಬಲವನ್ನು ಸಂಪರ್ಕಿಸಿ.",
  "subscribe.noPaymentNote": "ಇಲ್ಲಿ ಯಾವುದೇ ಪಾವತಿಯನ್ನು ತೆಗೆದುಕೊಳ್ಳಲಾಗುತ್ತಿಲ್ಲ, ಮತ್ತು ಯಾವುದೇ ಪರೀಕ್ಷೆ ಪ್ರಾರಂಭವಾಗಿಲ್ಲ — ಕಾರ್ಯಕ್ಷೇತ್ರವನ್ನು ಆರಿಸುವುದು ಚಂದಾದಾರಿಕೆಯನ್ನು ಅದಕ್ಕೆ ಮಾತ್ರ ಸಂಪರ್ಕಿಸುತ್ತದೆ.",
