  "subscribe.checkingTrial": "ನಿಮ್ಮ ಇಮೇಲ್‌ಗಾಗಿ ಉಚಿತ ಪರೀಕ್ಷೆ ಲಭ್ಯವಿದೆಯೇ ಎಂದು ಪರಿಶೀಲಿಸಲಾಗುತ್ತಿದೆ…",
  "subscribe.trialEligible": "ಅರ್ಹ ಹೊಸ ಗ್ರಾಹಕರಿಗೆ ಒಂದು 7 ದಿನಗಳ ಉಚಿತ ಪರೀಕ್ಷೆ ಸಿಗುತ್ತದೆ. ಇಂದು ನಿಮಗೆ ಶುಲ್ಕ ವಿಧಿಸಲಾಗುವುದಿಲ್ಲ — ನೀವು ಮೊದಲು ರದ್ದುಗೊಳಿಸದ ಹೊರತು ಪರೀಕ್ಷೆ ಮುಗಿದಾಗ ನಿಮ್ಮ ಮೊದಲ ಪಾವತಿ {price} ಬಾಕಿಯಾಗುತ್ತದೆ.",
