  "subscribe.subscribeButton": "{planName} ಗೆ ಚಂದಾದಾರರಾಗಿ — {price}/ತಿಂಗಳು",
  "subscribe.checkoutFailed": "ಚೆಕ್‌ಔಟ್ ಪ್ರಾರಂಭಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಯಾವುದಕ್ಕೂ ಶುಲ್ಕ ವಿಧಿಸಲಾಗಿಲ್ಲ.",
  "subscribe.stripeNote": "ಚೆಕ್‌ಔಟ್ ಅನ್ನು Stripe ಸುರಕ್ಷಿತವಾಗಿ ನಿರ್ವಹಿಸುತ್ತದೆ. ನೀವು ಯಾವುದೇ ಶುಲ್ಕವನ್ನು ಅನುಮೋದಿಸುವ ಮೊದಲು ನಿಖರವಾದ ಒಟ್ಟು ಮೊತ್ತವನ್ನು ನೀವು ನೋಡುತ್ತೀರಿ.",
  "subscribe.noCardStored": "Luminous StockHaven ಯಾವುದೇ ಕಾರ್ಡ್ ವಿವರಗಳನ್ನು ಸಂಗ್ರಹಿಸುವುದಿಲ್ಲ. ಪಾವತಿಗಳನ್ನು Stripe ಪ್ರಕ್ರಿಯೆಗೊಳಿಸುತ್ತದೆ.",
  "plans.backToWelcome": "ಸ್ವಾಗತಕ್ಕೆ ಹಿಂತಿರುಗಿ",
  "plans.eyebrow": "ಯೋಜನೆಗಳು ಮತ್ತು ವೈಶಿಷ್ಟ್ಯಗಳು",
  "plans.title": "StockHaven ಯೋಜನೆಗಳನ್ನು ಹೋಲಿಸಿ",
  "plans.intro": "ನೀವು ಯಾವುದೇ ಯೋಜನೆಯನ್ನು ಆರಿಸಿದರೂ ಒಂದು ಖಾತೆ — Business ಐದು ವ್ಯವಹಾರಗಳವರೆಗೆ ಒಳಗೊಳ್ಳುತ್ತದೆ. ಬೆಲೆಗಳು US ಡಾಲರ್‌ಗಳಲ್ಲಿ ಮಾಸಿಕವಾಗಿವೆ, ಮತ್ತು ಅರ್ಹ ಹೊಸ ವೆಬ್‌ಸೈಟ್ ಗ್ರಾಹಕರು Essentials ಮತ್ತು Business ನಲ್ಲಿ ಒಂದು ಏಳು ದಿನಗಳ ಪರೀಕ್ಷೆಯನ್ನು ಪಡೆಯಬಹುದು. ಅಸ್ತಿತ್ವದಲ್ಲಿರುವ Essentials ಚಂದಾದಾರಿಕೆಯನ್ನು Business ಗೆ ಅಪ್‌ಗ್ರೇಡ್ ಮಾಡುವುದರಿಂದ ಪರೀಕ್ಷೆ ಮರುಪ್ರಾರಂಭವಾಗುವುದಿಲ್ಲ ಅಥವಾ ಮತ್ತೊಂದು ಉಚಿತ ಪರೀಕ್ಷೆ ರಚನೆಯಾಗುವುದಿಲ್ಲ. ವೆಬ್‌ಸೈಟ್ ಯೋಜನೆಯ ಬೆಲೆಗಳು ಅನ್ವಯವಾಗುವ ತೆರಿಗೆಗಳ ಮೊದಲು, ಯಾವುದಾದರೂ ಇದ್ದರೆ. ನೀವು ಚಂದಾದಾರಿಕೆಯನ್ನು ಅಧಿಕೃತಗೊಳಿಸುವ ಮೊದಲು ನಿಮ್ಮ ನಿಖರವಾದ ಶುಲ್ಕವನ್ನು ತೋರಿಸಲಾಗುತ್ತದೆ.",
  "plans.availableAtLaunch": "ಮೊಬೈಲ್ ಬಿಡುಗಡೆಯಲ್ಲಿ ಲಭ್ಯ",
  "plans.yourPlan": "ನಿಮ್ಮ ಯೋಜನೆ",
  "plans.currentPlan": "ಪ್ರಸ್ತುತ ಯೋಜನೆ",
  "plans.changePlan": "ಯೋಜನೆಯನ್ನು ಬದಲಾಯಿಸಿ",
  "plans.subscribe": "ಚಂದಾದಾರರಾಗಿ",
  "plans.featureHeader": "ವೈಶಿಷ್ಟ್ಯ",
  "plans.perMonthShort": "/ತಿಂಗಳು",
  "plans.included": "ಒಳಗೊಂಡಿದೆ",
  "plans.notIncluded": "ಒಳಗೊಂಡಿಲ್ಲ",
  "plans.mobileIncludedNote": "ಎರಡೂ ವೆಬ್‌ಸೈಟ್ ಯೋಜನೆಗಳು ಮೊಬೈಲ್ ಸಹಾಯಕವನ್ನು ಒಳಗೊಂಡಿರುತ್ತವೆ, ಆದ್ದರಿಂದ ವೆಬ್‌ಸೈಟ್ ಚಂದಾದಾರರು ಮಾಸಿಕ ಮೊಬೈಲ್ ಶುಲ್ಕವನ್ನೂ ಪಾವತಿಸುವುದಿಲ್ಲ.",
  "plans.priceNote": "Essentials ತಿಂಗಳಿಗೆ $14.99 ಜೊತೆಗೆ ಅನ್ವಯವಾಗುವ ತೆರಿಗೆಗಳು, ಯಾವುದಾದರೂ ಇದ್ದರೆ. Business ತಿಂಗಳಿಗೆ $29.99 ಜೊತೆಗೆ ಅನ್ವಯವಾಗುವ ತೆರಿಗೆಗಳು, ಯಾವುದಾದರೂ ಇದ್ದರೆ. ಯಾವುದೇ ಅಗತ್ಯವಿರುವ ತೆರಿಗೆಯನ್ನು ಪೂರೈಕೆದಾರರ ಚೆಕ್‌ಔಟ್ ಸಮಯದಲ್ಲಿ ನಿರ್ಧರಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಪಾವತಿಯ ಮೊದಲು ಅಂತಿಮ ಒಟ್ಟು ಮೊತ್ತದಲ್ಲಿ ಕಾಣಿಸಬೇಕು. ಈ ಹೋಲಿಕೆ ಪುಟವು ತೆರಿಗೆ ಉಲ್ಲೇಖ ಅಥವಾ ಪಾವತಿ ಅಧಿಕಾರವಲ್ಲ.",
  "plans.mobilePriceNote": "ಮೊಬೈಲ್-ಮಾತ್ರ ಯೋಜನೆಯು ಅದರ ಉದ್ದೇಶಿತ U.S. ಮೂಲ ಬೆಲೆಯಲ್ಲಿ ತಿಂಗಳಿಗೆ $4.99 ಆಗಿದೆ. App Store ಅಥವಾ Google Play ಖರೀದಿಯ ಮೊದಲು ನಿಜವಾದ ಸ್ಥಳೀಯ ಚಂದಾದಾರಿಕೆ ಬೆಲೆ ಮತ್ತು ಯಾವುದೇ ಅನ್ವಯವಾಗುವ ತೆರಿಗೆಗಳನ್ನು ತೋರಿಸುತ್ತದೆ. ಅದರ ಉತ್ಪನ್ನ, ಸೈಟ್ ಮತ್ತು ಸಿಬ್ಬಂದಿ ಭತ್ಯೆಗಳನ್ನು ವೆಬ್‌ಸೈಟ್ ಶ್ರೇಣಿಗಳಿಂದ ಪ್ರತ್ಯೇಕವಾಗಿ ಬಿಡುಗಡೆಯಲ್ಲಿ ಹೊಂದಿಸಲಾಗುತ್ತದೆ.",
  "plans.planChangeNote": "ವೆಬ್‌ಸೈಟ್ ಯೋಜನೆಯ ಬದಲಾವಣೆಯನ್ನು ಬಿಲ್ಲಿಂಗ್ ಪೂರೈಕೆದಾರರು ದೃಢೀಕರಿಸಬೇಕು. ಬದಲಾವಣೆಯನ್ನು ಅಧಿಕೃತಗೊಳಿಸುವ ಮೊದಲು ಹೊಸ ಬೆಲೆ, ಜಾರಿ ದಿನಾಂಕ ಮತ್ತು ಯಾವುದೇ ಪ್ರೊರೇಷನ್ ಅನ್ನು ವಿವರಿಸಲಾಗುತ್ತದೆ. ಅಪ್‌ಗ್ರೇಡ್ ಎರಡನೇ ಚಂದಾದಾರಿಕೆಯನ್ನು ರಚಿಸಬಾರದು.",
  "plans.providerNote": "ಬೆಲೆಗಳು, ಶುಲ್ಕಗಳು ಮತ್ತು ಪರೀಕ್ಷೆಗಳನ್ನು ನೀವು ಚಂದಾದಾರರಾಗುವ ಪೂರೈಕೆದಾರರು ನಿರ್ವಹಿಸುತ್ತಾರೆ — App Store, Google Play, ವೆಬ್‌ಸೈಟ್ ಅಥವಾ Shopify — ಈ ಪುಟದಿಂದ ಎಂದಿಗೂ ಅಲ್ಲ.",
  "plans.reviewBefore": "ಚಂದಾದಾರರಾಗುವ ಮೊದಲು, ದಯವಿಟ್ಟು ಪರಿಶೀಲಿಸಿ",
