  "plans.priceNoteGrandfathered": "ಪಟ್ಟಿ ಮಾಡಿದ ಯೋಜನೆಯ ಬೆಲೆ ಮಾತ್ರ — ನಿಮ್ಮ ಪರಿಚಾರಕ ಬಿಡುಗಡೆ-ಪೂರ್ವ ಪ್ರವೇಶಕ್ಕೆ ಶುಲ್ಕ ವಿಧಿಸಲಾಗುವುದಿಲ್ಲ.",
