  "upgrade.eyebrow": "ಯೋಜನೆಗಳು",
  "upgrade.title": "ನಿಮ್ಮ ಅಂಗಡಿಗೆ ಯಾವುದು ಹೊಂದುತ್ತದೆ ಎಂಬುದನ್ನು ಆರಿಸಿ",
  "upgrade.pendingCheckoutIntro": "ನೀವು ಚಂದಾದಾರಿಕೆಯನ್ನು ಆರಿಸುವವರೆಗೆ ಈ ಹೊಸ ಕಾರ್ಯಕ್ಷೇತ್ರವು Essentials ಗೆ ಸೀಮಿತವಾಗಿದೆ. ಅರ್ಹ ಹೊಸ ಗ್ರಾಹಕರು ಪ್ರತಿ ಖಾತೆಗೆ ಒಂದು {days} ದಿನಗಳ ಪರೀಕ್ಷೆಯನ್ನು ಪಡೆಯಬಹುದು.",
  "upgrade.intro": "ಅರ್ಹ ಹೊಸ ಗ್ರಾಹಕರು ಪ್ರತಿ ಖಾತೆಗೆ ಒಂದು {days} ದಿನಗಳ ಪರೀಕ್ಷೆಯನ್ನು ಪಡೆಯಬಹುದು, ಪ್ರತಿ ಯೋಜನೆಗೆ ಒಂದು ಪರೀಕ್ಷೆ ಅಲ್ಲ. Essentials ನಿಂದ Business ಗೆ ಬದಲಾಯಿಸುವುದರಿಂದ ಮತ್ತೊಂದು ಉಚಿತ ಪರೀಕ್ಷೆ ಎಂದಿಗೂ ಪ್ರಾರಂಭವಾಗುವುದಿಲ್ಲ. ನೀವು ಇದರಲ್ಲಿದ್ದೀರಿ",
  "upgrade.introGrandfathered": " — ಪೂರ್ಣ Business ಕಾರ್ಯಕ್ಷೇತ್ರ, ಯಾವುದೇ ಶುಲ್ಕವಿಲ್ಲದೆ.",
  "upgrade.introTrial": " (ಪರೀಕ್ಷೆ).",
  "upgrade.introPeriod": ".",
  "upgrade.pastDueTitle": "ಪಾವತಿ ಬಾಕಿಯಾಗಿದೆ",
  "upgrade.pastDueBody": "ನಿಮ್ಮ ಕೊನೆಯ ಪಾವತಿ ನಡೆಯಲಿಲ್ಲ, ಆದ್ದರಿಂದ ಈ ಚಂದಾದಾರಿಕೆ ಬಾಕಿಯಾಗಿದೆ. ಕೆಳಗೆ ನಿಮ್ಮ ಪಾವತಿ ವಿಧಾನವನ್ನು ನವೀಕರಿಸಿ — Stripe ತನ್ನದೇ ವೇಳಾಪಟ್ಟಿಯಲ್ಲಿ ಮರುಪ್ರಯತ್ನಿಸುತ್ತದೆ, ಮತ್ತು ನಿಮ್ಮ ಚಂದಾದಾರಿಕೆಯನ್ನು ಬೇಗ ರದ್ದುಗೊಳಿಸಲಾಗುವುದಿಲ್ಲ. ನಿಮಗೆ ಸಹಾಯ ಬೇಕಾದರೆ, ಇಮೇಲ್ ಮಾಡಿ",
  "upgrade.updatePaymentMethod": "ಪಾವತಿ ವಿಧಾನವನ್ನು ನವೀಕರಿಸಿ",
  "upgrade.startingPaymentUpdate": "ಪಾವತಿ ನವೀಕರಣ ಪ್ರಾರಂಭಿಸಲಾಗುತ್ತಿದೆ…",
  "upgrade.paymentUpdateFailed": "ಪಾವತಿ ನವೀಕರಣವನ್ನು ಪ್ರಾರಂಭಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.",
