  "upgrade.taxNote": "ಜೊತೆಗೆ ಅನ್ವಯವಾಗುವ ತೆರಿಗೆಗಳು, ಯಾವುದಾದರೂ ಇದ್ದರೆ. ನೀವು ಶುಲ್ಕವನ್ನು ಅನುಮೋದಿಸುವ ಮೊದಲು ಪೂರೈಕೆದಾರರು ನಿಮ್ಮ ನಿಖರವಾದ ಒಟ್ಟು ಮೊತ್ತವನ್ನು ತೋರಿಸಬೇಕು.",
  "upgrade.startSubscription": "ಚಂದಾದಾರಿಕೆಯನ್ನು ಪ್ರಾರಂಭಿಸಿ",
  "upgrade.trialCheckedNote": "ಅರ್ಹ ಹೊಸ ಗ್ರಾಹಕರಿಗೆ ಒಂದು 7 ದಿನಗಳ ಉಚಿತ ಪರೀಕ್ಷೆ ಸಿಗುತ್ತದೆ — ಚೆಕ್‌ಔಟ್‌ಗಿಂತ ಮೊದಲು ಸರ್ವರ್‌ನಿಂದ ಪರಿಶೀಲಿಸಲಾಗುತ್ತದೆ.",
  "upgrade.upgradeToBusiness": "Business ಗೆ ಅಪ್‌ಗ್ರೇಡ್ ಮಾಡಿ",
  "upgrade.upgradeNote": "ಅದೇ ಚಂದಾದಾರಿಕೆ, ಎರಡನೇ ಪರೀಕ್ಷೆ ಇಲ್ಲ, ತಕ್ಷಣದ ಶುಲ್ಕವಿಲ್ಲ — ಬೆಲೆ ವ್ಯತ್ಯಾಸವು ನಿಮ್ಮ ಮುಂದಿನ ಇನ್‌ವಾಯ್ಸ್‌ನಲ್ಲಿ ಬರುತ್ತದೆ.",
  "upgrade.upgradeTrialNote": "ನಿಮ್ಮ ಪರೀಕ್ಷೆ {date} ವರೆಗೆ ಮುಂದುವರಿಯುತ್ತದೆ, ನಂತರ Business ತಿಂಗಳಿಗೆ $29.99 ರಲ್ಲಿ ಪ್ರಾರಂಭವಾಗುತ್ತದೆ.",
