  "billing.readiness.trialAlreadyUsed": "ಪರಿಚಯಾತ್ಮಕ ಪರೀಕ್ಷೆಯನ್ನು ಈಗಾಗಲೇ ಬಳಸಲಾಗಿದೆ ಅಥವಾ ಕಾಯ್ದಿರಿಸಲಾಗಿದೆ. ಯಾವುದೇ ಪುನರಾವರ್ತಿತ ಪರೀಕ್ಷೆ ಪ್ರಾರಂಭವಾಗಬಾರದು.",
  "billing.readiness.trialEligibilityUnverified": "ಈ ಮಾಲೀಕರಿಗಾಗಿ ಏಕ-ಬಾರಿ ಪರೀಕ್ಷೆ ಅರ್ಹತೆಯನ್ನು ಪರಿಶೀಲಿಸಲಾಗಿಲ್ಲ. ಚೆಕ್‌ಔಟ್ ನಿರ್ಬಂಧಿತವಾಗಿಯೇ ಉಳಿದಿದೆ.",
