  "billing.readiness.entitlementNotUnique": "ಅಸ್ತಿತ್ವದಲ್ಲಿರುವ ಯೋಜನೆ ಮಾಹಿತಿ ಕಾಣೆಯಾಗಿದೆ ಅಥವಾ ಅಸ್ಪಷ್ಟವಾಗಿದೆ. ಯಾವುದೇ ಚೆಕ್‌ಔಟ್ ಪ್ರಾರಂಭವಾಗಬಾರದು.",
  "billing.readiness.accountBillingIncomplete": "ಖಾತೆ ಬಿಲ್ಲಿಂಗ್ ಇತಿಹಾಸವನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ಓದಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಯಾವುದೇ ಚೆಕ್‌ಔಟ್ ಪ್ರಾರಂಭವಾಗಬಾರದು.",
  "billing.readiness.billingHistoryIncomplete": "ಸಂಪೂರ್ಣ ಮಾಲೀಕ ಇತಿಹಾಸವನ್ನು ಪರಿಶೀಲಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಯಾವುದೇ ಚೆಕ್‌ಔಟ್ ಪ್ರಾರಂಭವಾಗಬಾರದು.",
  "billing.readiness.ownershipMismatch": "ಯಾವುದೇ ಚಂದಾದಾರಿಕೆಯನ್ನು ಪ್ರಾರಂಭಿಸುವ ಮೊದಲು ಖಾತೆ ಮಾಲೀಕತ್ವ ಅಥವಾ ಬಿಲ್ಲಿಂಗ್ ದಾಖಲೆಗಳಿಗೆ ಪರಿಶೀಲನೆ ಅಗತ್ಯ.",
