  "billing.dryRun.ariaLabel": "ಪರೀಕ್ಷಾ ಅಪ್‌ಗ್ರೇಡ್ ಸಿಮ್ಯುಲೇಶನ್",
  "billing.dryRun.title": "Essentials → Business — ಅಭ್ಯಾಸ ಸಿಮ್ಯುಲೇಶನ್",
  "billing.dryRun.body": "ಈ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಸಂಪೂರ್ಣವಾಗಿ ಕಾಲ್ಪನಿಕ ದಾಖಲೆಗಳನ್ನು ಬಳಸಿ ಪ್ರಸ್ತಾವಿತ ಅಪ್‌ಗ್ರೇಡ್ ನಿಯಮಗಳನ್ನು ಅಭ್ಯಾಸ ಮಾಡಿ. ಇದು ನಿಮ್ಮ ನಿಜವಾದ TEST — ಪೈಜಾಮಾ ಪ್ಯಾಂಟ್ ಮಾದರಿ, ನಿಮ್ಮ ಪ್ರಸ್ತುತ Business ಕಾರ್ಯಕ್ಷೇತ್ರ, Stripe, ಪರೀಕ್ಷೆಗಳು, ಚಂದಾದಾರಿಕೆಗಳು ಅಥವಾ ದಾಸ್ತಾನನ್ನು ಓದುವುದಿಲ್ಲ ಅಥವಾ ಬದಲಾಯಿಸುವುದಿಲ್ಲ.",
  "billing.dryRun.runButton": "ಸ್ಥಳೀಯ ಅಪ್‌ಗ್ರೇಡ್ ಸಿಮ್ಯುಲೇಶನ್ ಚಲಾಯಿಸಿ (ಶುಲ್ಕವಿಲ್ಲ)",
  "billing.dryRun.passed": "ಕಾಲ್ಪನಿಕ ಸನ್ನಿವೇಶವು ಅದರ ಸ್ಥಳೀಯ ಪರಿಶೀಲನೆಗಳನ್ನು ದಾಟಿತು",
  "billing.dryRun.blocked": "ಕಾಲ್ಪನಿಕ ಸನ್ನಿವೇಶವನ್ನು ನಿರ್ಬಂಧಿಸಲಾಗಿದೆ",
  "billing.dryRun.example": "ಉದಾಹರಣೆ: Essentials ($14.99/ತಿಂಗಳು) → Business ($29.99/ತಿಂಗಳು), ಯಾವುದೇ ಅನ್ವಯವಾಗುವ ತೆರಿಗೆಯ ಮೊದಲು.",
  "billing.dryRun.preserved": "ಅದೇ ಚಂದಾದಾರಿಕೆಯನ್ನು ಉಳಿಸಿಕೊಳ್ಳಲಾಗಿದೆ, ಒಂದು ಮೂಲ ಪರೀಕ್ಷೆಯನ್ನು ಉಳಿಸಿಕೊಳ್ಳಲಾಗಿದೆ, ಮತ್ತು ಸಿಮ್ಯುಲೇಟೆಡ್ ಪೈಜಾಮಾ ದಾಸ್ತಾನು ಬದಲಾಗಿಲ್ಲ. ನಿಜವಾದ, ಪೂರೈಕೆದಾರ-ದೃಢೀಕರಿಸಿದ ಪಾವತಿಸಿದ ನವೀಕರಣವು ಪ್ರವೇಶವನ್ನು ಬದಲಾಯಿಸುವುದನ್ನು ಸಮರ್ಥಿಸುವವರೆಗೆ ಉದಾಹರಣೆ ಗ್ರಾಹಕರು Essentials ನಲ್ಲಿಯೇ ಉಳಿಯುತ್ತಾರೆ.",
  "billing.dryRun.limitations": "ಸ್ಥಳೀಯ ಸಿಮ್ಯುಲೇಶನ್ Stripe ಚಂದಾದಾರಿಕೆ ಬದಲಾವಣೆಗಳು, ಪಾವತಿ, ವೆಬ್‌ಹುಕ್, ತೆರಿಗೆ-ಒಳಗೊಂಡ ಉಲ್ಲೇಖ, ನೇರ ಚಂದಾದಾರಿಕೆ ಅಥವಾ ನಿಮ್ಮ ನಿಜವಾದ ವ್ಯವಹಾರ ದಾಖಲೆಗಳನ್ನು ಪರೀಕ್ಷಿಸುವುದಿಲ್ಲ.",
