  "exports.exportFailedDesc": "{title} ಅನ್ನು ನಿರ್ಮಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
  "exports.excelWorkbook": "Excel ಕಾರ್ಯಪುಸ್ತಕ",
