  "import.eyebrow": "ಡೇಟಾ",
  "import.title": "ಆಮದು ಕೇಂದ್ರ",
  "import.subtitleStart": "ಮೂರು ಪ್ರತ್ಯೇಕ ಸ್ಪ್ರೆಡ್‌ಶೀಟ್ ಕಾರ್ಯಾಚರಣೆಗಳು, ಆದ್ದರಿಂದ ಬೆಲೆ ತಿದ್ದುಪಡಿಯು ಎಂದಿಗೂ ದಾಸ್ತಾನು ರಸೀದಿಯಾಗಿ ಬರಲು ಸಾಧ್ಯವಿಲ್ಲ. ಎಲ್ಲವೂ ಇಲ್ಲಿ ಬರುತ್ತದೆ",
  "import.subtitleRest": " ಮಾತ್ರ, ಮತ್ತು ಡ್ರೈ ರನ್ ದಾಟುವವರೆಗೆ ಏನನ್ನೂ ಬರೆಯಲಾಗುವುದಿಲ್ಲ.",
  "import.createBusinessFirst": "ಮೊದಲು ವ್ಯವಹಾರವನ್ನು ರಚಿಸಿ — ಆಮದು ಮಾಡಿದ ಉತ್ಪನ್ನಗಳು ವ್ಯವಹಾರಕ್ಕೆ ಸೇರುತ್ತವೆ.",
  "import.createBusinessFirstShort": "ಮೊದಲು ವ್ಯವಹಾರವನ್ನು ರಚಿಸಿ.",
  "import.whatEachDoes": "ಪ್ರತಿ ಕಾರ್ಯಾಚರಣೆಯು ಏನು ಮಾಡುತ್ತದೆ",
  "import.createTitle": "ಹೊಸ ಉತ್ಪನ್ನಗಳನ್ನು ರಚಿಸಿ",
  "import.createDesc": "ಇನ್ನೂ ಕ್ಯಾಟಲಾಗ್‌ನಲ್ಲಿ ಇಲ್ಲದ ಸಾಲುಗಳನ್ನು ಸೇರಿಸುತ್ತದೆ. ಈಗಾಗಲೇ ಬಳಕೆಯಲ್ಲಿರುವ ನಕಲು SKU ಗಳು ಮತ್ತು ಬಾರ್‌ಕೋಡ್‌ಗಳನ್ನು ಬಿಟ್ಟುಬಿಡಲಾಗುತ್ತದೆ, ಮತ್ತು ಆರಂಭಿಕ ದಾಸ್ತಾನು ನೀವು ಆರಿಸುವ ಸ್ಥಳದಲ್ಲಿ ರಸೀದಿಯಾಗಿ ಬರಬಹುದು.",
  "import.updateTitle": "ಅಸ್ತಿತ್ವದಲ್ಲಿರುವ ಉತ್ಪನ್ನಗಳನ್ನು ನವೀಕರಿಸಿ",
  "import.updateDesc": "ಪ್ರತಿ ಸಾಲನ್ನು SKU ಅಥವಾ ದಾಖಲೆ ID ನಿಂದ ಹೊಂದಿಸುತ್ತದೆ ಮತ್ತು ಹಳೆಯ ಮೌಲ್ಯವನ್ನು ಪ್ರಸ್ತಾವಿತ ಹೊಸದರ ಪಕ್ಕದಲ್ಲಿ ತೋರಿಸುತ್ತದೆ. ನೀವು ಖಾಲಿಗಳನ್ನು ತೆರವುಗೊಳಿಸಲು ಕೇಳದ ಹೊರತು ಖಾಲಿ ಕೋಶಗಳು ಉಳಿಸಿದ ಮೌಲ್ಯವನ್ನು ಹಾಗೆಯೇ ಬಿಡುತ್ತವೆ, ಮತ್ತು ಪ್ರಮಾಣಗಳನ್ನು ಎಂದಿಗೂ ಮುಟ್ಟಲಾಗುವುದಿಲ್ಲ.",
  "import.receiveModeTitle": "ದಾಸ್ತಾನನ್ನು ಸ್ವೀಕರಿಸಿ",
  "import.receiveModeDesc": "ಬರುವ ಪ್ರಮಾಣಗಳನ್ನು ಒಂದು ಸ್ಥಳಕ್ಕೆ ಸೇರಿಸುತ್ತದೆ ಮತ್ತು ಪ್ರತಿ ಸಾಲಿಗೆ ಚಲನೆ ಲೆಡ್ಜರ್‌ಗೆ ರಸೀದಿಯನ್ನು ಬರೆಯುತ್ತದೆ. ಪ್ರತಿ ಬ್ಯಾಚ್ ಅನ್ನು ಗುರುತಿಸಲಾಗಿದೆ, ಆದ್ದರಿಂದ ಒಂದೇ ಶೀಟ್ ಅನ್ನು ಎರಡು ಬಾರಿ ಸ್ವೀಕರಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.",
  "import.excelNote": "Excel ಕಾರ್ಯಪುಸ್ತಕಗಳನ್ನು (.xlsx) ನೇರವಾಗಿ ಓದಲಾಗುತ್ತದೆ — ಕಾರ್ಯಶೀಟ್ ಅನ್ನು ಆರಿಸಿ ಮತ್ತು ಕಾಲಮ್‌ಗಳನ್ನು ನಿಮಗಾಗಿ ಹೊಂದಿಸಲಾಗುತ್ತದೆ. ಕೋಡ್‌ಗಳು ಸಂಪೂರ್ಣವಾಗಿ ಉಳಿಯುತ್ತವೆ: ಪಠ್ಯವಾಗಿ ಉಳಿಸಿದ UPC ಅದರ ಅಂಕೆಗಳು ಮತ್ತು ಮುಂಚೂಣಿಯ ಸೊನ್ನೆಗಳನ್ನು ಉಳಿಸಿಕೊಳ್ಳುತ್ತದೆ. ಆಮದು ಮಾಡಲು ಸಾಧ್ಯವಾಗದ ಸಾಲುಗಳನ್ನು ಕಾರಣದೊಂದಿಗೆ ಪಟ್ಟಿ ಮಾಡಲಾಗಿದೆ",
  "import.excelNoteDownload": " ಮತ್ತು ಫೈಲ್ ಆಗಿ ಡೌನ್‌ಲೋಡ್ ಮಾಡಬಹುದು.",
  "import.excelNoteFix": ", ಆದ್ದರಿಂದ ನೀವು ಅವುಗಳನ್ನು ಸರಿಪಡಿಸಿ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಬಹುದು.",
