  "reports.lockedTitle": "ಸುಧಾರಿತ ವರದಿಗಳು Business ವೈಶಿಷ್ಟ್ಯವಾಗಿದೆ",
  "reports.lockedDesc": "ನಿಮ್ಮ ಕಾರ್ಯಕ್ಷೇತ್ರವು Essentials ಯೋಜನೆಯಲ್ಲಿದೆ. Business ಸುಧಾರಿತ ವರದಿಗಳು, ದಾಸ್ತಾನು ಮೌಲ್ಯಮಾಪನ, ಅನಿಯಮಿತ ಉತ್ಪನ್ನಗಳು ಮತ್ತು ಸಿಬ್ಬಂದಿ, ಪೂರೈಕೆದಾರರು, ಖರೀದಿ, ರಫ್ತುಗಳು ಮತ್ತು ಬಂಡಲ್‌ಗಳನ್ನು ಸೇರಿಸುತ್ತದೆ.",
