  "reports.stockRecordsHint": "ದಾಸ್ತಾನನ್ನು ಹೊಂದಿರುವ ಸ್ಥಳ ದಾಖಲೆಗಳು",
  "reports.movementsHint": "ಎಣಿಸಿದ ಲೆಡ್ಜರ್ ನಮೂದುಗಳು",
  "reports.biggest": "ಅತಿದೊಡ್ಡ {group}",
  "reports.nothingToRank": "ಇನ್ನೂ ಶ್ರೇಣೀಕರಿಸಲು ಏನೂ ಇಲ್ಲ",
  "reports.missingMoney": "ಈ ವೀಕ್ಷಣೆಯಲ್ಲಿ {units} ಘಟಕಗಳಿಗೆ ಯಾವುದೇ {label} ದಾಖಲಾಗಿಲ್ಲ. ಕಾಣೆಯಾದ ಹಣವನ್ನು ಎಂದಿಗೂ ಸೊನ್ನೆಯಾಗಿ ಪರಿಗಣಿಸಲಾಗುವುದಿಲ್ಲ — ಅವುಗಳನ್ನು ಉಚಿತವಾಗಿ ಎಣಿಸುವ ಬದಲು ಅಂಕಿ-ಅಂಶಗಳಿಂದ ಬಿಡಲಾಗುತ್ತದೆ. ಆ ಉತ್ಪನ್ನಗಳಲ್ಲಿ ಅಂಕಿ-ಅಂಶವನ್ನು ಸೇರಿಸಿ ಮತ್ತು ಒಟ್ಟು ಮೊತ್ತಗಳು ತುಂಬುತ್ತವೆ.",
  "reports.movementsCapped": "ಕೇವಲ ಹೊಸ {cap} ಲೆಡ್ಜರ್ ನಮೂದುಗಳನ್ನು ಮಾತ್ರ ಓದಲಾಗಿದೆ, ಆದ್ದರಿಂದ ಇವುಗಳಿಗಿಂತ ಹಳೆಯ ಚಲನೆಗಳು ಒಟ್ಟು ಮೊತ್ತಗಳಲ್ಲಿ ಇಲ್ಲ. ವಿಂಡೋಗೆ ನಿಖರವಾದ ಅಂಕಿ-ಅಂಶಗಳನ್ನು ನೋಡಲು ಅವಧಿಯನ್ನು ಸಂಕುಚಿತಗೊಳಿಸಿ.",
  "reports.footnote": "ಮಾರಾಟಗಳು ಪ್ರತಿ ಉತ್ಪನ್ನದ ಪ್ರಸ್ತುತ ಚಿಲ್ಲರೆ ಬೆಲೆಯನ್ನು ಬಳಸುತ್ತವೆ, ರಸೀದಿಗಳು ದಾಸ್ತಾನು ಬಂದಾಗ ದಾಖಲಾದ ವೆಚ್ಚವನ್ನು ಬಳಸುತ್ತವೆ, ಮತ್ತು ನಷ್ಟಗಳು ಪ್ರಸ್ತುತ ಘಟಕ ವೆಚ್ಚವನ್ನು ಬಳಸುತ್ತವೆ. ಕಾಣೆಯಾದ ಹಣವನ್ನು ಎಂದಿಗೂ ಸೊನ್ನೆಯಾಗಿ ಪರಿಗಣಿಸಲಾಗುವುದಿಲ್ಲ — ಅದು ತಿಳಿಯುವವರೆಗೆ ಅಂಕಿ-ಅಂಶವನ್ನು ಖಾಲಿ ಬಿಡಿ. ವರದಿಯು ಒಂದು ವೀಕ್ಷಣೆಯಾಗಿದೆ, ದಾಖಲೆಯಲ್ಲ: ನೀವು ಒಂದನ್ನು ಚಲಾಯಿಸಿದಾಗ ನಿಮ್ಮ ದಾಖಲೆಗಳಿಗೆ ಏನನ್ನೂ ಬರೆಯಲಾಗುವುದಿಲ್ಲ.",
  "reports.createBusinessFirst": "ಮೊದಲು ವ್ಯವಹಾರವನ್ನು ರಚಿಸಿ — ವರದಿಗಳನ್ನು ಪ್ರತಿ ವ್ಯವಹಾರಕ್ಕೆ ಎಣಿಸಲಾಗುತ್ತದೆ.",
