  "print.howIntro": "ಈ ಅಪ್ಲಿಕೇಶನ್ ನೀವು ಈಗಾಗಲೇ ಹೊಂದಿರುವ ಪ್ರಿಂಟರ್‌ಗಳಿಗೆ ಸಂಪರ್ಕಿಸುತ್ತದೆ — ಅದು ಸ್ವತಃ ಪ್ರಿಂಟರ್ ಅಲ್ಲ. ಅದನ್ನು ತಲುಪಲು ನಾಲ್ಕು ಮಾರ್ಗಗಳಿವೆ, ಮತ್ತು ಲೇಬಲ್‌ಗಳು ಅವುಗಳಲ್ಲಿ ಯಾವುದರ ಮೂಲಕವಾದರೂ ಎರಡೂ ಯೋಜನೆಗಳಲ್ಲಿ ಮುದ್ರಿಸುತ್ತವೆ. ಪ್ಯಾಕಿಂಗ್ ಸ್ಲಿಪ್‌ಗಳು, ಖರೀದಿ ಆದೇಶಗಳು, ಪೂರೈಕೆದಾರ ದಾಖಲೆಗಳು ಮತ್ತು ವರದಿಗಳು Business-ಮಾತ್ರ, ಸಂಪರ್ಕ ಯಾವುದೇ ಆದರೂ.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "ಈ ಪುಟದಿಂದ, ಡೆಸ್ಕ್‌ಟಾಪ್ Chrome ಅಥವಾ Edge ನಲ್ಲಿ ಮತ್ತು Android Chrome ನಲ್ಲಿ: ನಿಮ್ಮ ಲೇಬಲ್ ಪ್ರಿಂಟರ್ ಅನ್ನು ಆರಿಸಿ ಮತ್ತು ಲೇಬಲ್‌ಗಳು ನೇರವಾಗಿ ಅದಕ್ಕೆ ಹೋಗುತ್ತವೆ. ಇದು iOS Safari ನಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುವುದಿಲ್ಲ — iPhone ನಲ್ಲಿ, Bluetooth ಮುದ್ರಣವು ಬದಲಾಗಿ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್‌ನೊಂದಿಗೆ ಬರುತ್ತದೆ. ಕೇವಲ Zebra ZPL ಅಥವಾ Brother ನ ಸ್ವಂತ ಭಾಷೆಯನ್ನು ಮಾತನಾಡುವ ಪ್ರಿಂಟರ್ ಈ ಪುಟ ಕಳುಹಿಸುವ ಲೇಬಲ್‌ಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳುವುದಿಲ್ಲ; ಅದನ್ನು ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ ಎಂದು ಹೇಳುವ ಮೊದಲು ನಿಜವಾದ ಪ್ರಿಂಟರ್‌ಗಳ ವಿರುದ್ಧ ಪರಿಶೀಲಿಸಲಾಗುತ್ತದೆ.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "ನಿಮ್ಮ ಅಂಗಡಿಯ Wi-Fi ನಲ್ಲಿ ಪ್ರಿಂಟರ್ ಅನ್ನು ಸ್ಥಾಪಿಸಿ, ನಂತರ Print ಬಟನ್ ಬಳಸಿ — ಅದು ಈ ಕಂಪ್ಯೂಟರ್‌ನಲ್ಲಿ ಸ್ಥಾಪಿಸಲಾದ ಪ್ರಿಂಟರ್ ಮೂಲಕ, ಅಂಗಡಿ ನೆಟ್‌ವರ್ಕ್ ಮೂಲಕ ಮುದ್ರಿಸುತ್ತದೆ. iPhone ನಲ್ಲಿ, AirPrint ಅಂತರ್ನಿರ್ಮಿತವಾಗಿದೆ: ಅದೇ Wi-Fi ನಲ್ಲಿರುವ AirPrint ಪ್ರಿಂಟರ್ ಮುದ್ರಣ ಶೀಟ್‌ನಲ್ಲಿ ಕಾಣಿಸಿಕೊಳ್ಳುತ್ತದೆ, ಯಾವುದೇ ಕಾರ್ಡ್ ಮತ್ತು ಯಾವುದೇ ಅಪ್ಲಿಕೇಶನ್ ಅಗತ್ಯವಿಲ್ಲ, ಮತ್ತು ಅಪ್ಲಿಕೇಶನ್‌ಗೆ ಯಾವುದೇ AirPrint-ನಿರ್ದಿಷ್ಟ ಕೋಡ್ ಅಗತ್ಯವಿಲ್ಲ. ಪ್ರಿಂಟರ್ AirPrint ಅನ್ನು ಬೆಂಬಲಿಸಬೇಕು (ಹೆಚ್ಚಿನ ಹೊಸವುಗಳು ಮಾಡುತ್ತವೆ) ಮತ್ತು ಫೋನ್ ಮತ್ತು ಪ್ರಿಂಟರ್ ಒಂದೇ Wi-Fi ನಲ್ಲಿರಬೇಕು.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "ಪ್ರಿಂಟರ್ ಅನ್ನು Ethernet ಕಾರ್ಡ್‌ನೊಂದಿಗೆ ನಿಮ್ಮ ಅಂಗಡಿ ನೆಟ್‌ವರ್ಕ್‌ಗೆ ತಂತಿ ಮಾಡಿ, ಅದನ್ನು ಕಂಪ್ಯೂಟರ್‌ನಲ್ಲಿ ಸ್ಥಾಪಿಸಿ, ಮತ್ತು Print ಬಟನ್ ಮೂಲಕ ಮುದ್ರಿಸಿ. Ethernet ಡೆಸ್ಕ್‌ಟಾಪ್ ಮತ್ತು ಕಂಪ್ಯೂಟರ್ ಮಾರ್ಗವಾಗಿದೆ — iPhone ಗಳು Ethernet ಕಾರ್ಡ್‌ಗಳನ್ನು ಬಳಸುವುದಿಲ್ಲ.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "ಪ್ರಿಂಟರ್ ಅನ್ನು ಅದರ ಕಾರ್ಡ್‌ನೊಂದಿಗೆ ಕಂಪ್ಯೂಟರ್‌ಗೆ ಪ್ಲಗ್ ಮಾಡಿ ಮತ್ತು Print ಬಟನ್ ಬಳಸಿ — ಅದು ಅಲ್ಲಿ ಸ್ಥಾಪಿಸಲಾದ ಪ್ರಿಂಟರ್ ಮೂಲಕ ಮುದ್ರಿಸುತ್ತದೆ. USB OTG ಕೇಬಲ್‌ನೊಂದಿಗೆ Android ಫೋನ್‌ನಲ್ಲಿ, ಮೇಲಿನ USB ಬಟನ್ ನೇರವಾಗಿ ಪ್ರಿಂಟರ್‌ನೊಂದಿಗೆ ಮಾತನಾಡುತ್ತದೆ. iPhone ಗಳು ನೇರವಾಗಿ USB ಮೂಲಕ ಮುದ್ರಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ — ಅಲ್ಲಿ WebUSB ಇಲ್ಲ — ಆದ್ದರಿಂದ Wi-Fi / AirPrint ಬಳಸಿ, ಅಥವಾ ಮೊಬೈಲ್ ಅಪ್ಲಿಕೇಶನ್‌ನಿಂದ Bluetooth ಬಳಸಿ.",
  "print.howCordsLead": "ಕಾರ್ಡ್‌ಗಳು ಇನ್ನೂ iPhone ಗಳಿಗೆ ಸೇವೆ ಸಲ್ಲಿಸುತ್ತವೆ, ಒಂದು ಹೆಜ್ಜೆ ತೆಗೆದುಹಾಕಲಾಗಿದೆ.",
  "print.howCordsBody": "ಅಂಗಡಿ ಕಂಪ್ಯೂಟರ್‌ಗೆ ಪ್ಲಗ್ ಮಾಡಿದ USB ಪ್ರಿಂಟರ್, ಅಥವಾ ನೆಟ್‌ವರ್ಕ್‌ಗೆ ತಂತಿ ಮಾಡಿದ Ethernet ಪ್ರಿಂಟರ್, ನಿಮ್ಮ ಅಂಗಡಿ Wi-Fi ಮೂಲಕ ನಿಮ್ಮ iPhone ನಲ್ಲಿ ಕಾಣಿಸಿಕೊಳ್ಳುತ್ತದೆ (AirPrint / ಹಂಚಿದ ಪ್ರಿಂಟರ್) — ಕಾರ್ಡ್‌ಗಳು ಪ್ರಿಂಟರ್ ಅನ್ನು ನೆಟ್‌ವರ್ಕ್‌ನಲ್ಲಿ ದೃಢವಾಗಿ ಇರಿಸುತ್ತವೆ, ಮತ್ತು ಫೋನ್ ಅದನ್ನು ವೈರ್‌ಲೆಸ್ ಆಗಿ ತಲುಪುತ್ತದೆ.",
  "print.howOfflineLead": "ಇಂಟರ್ನೆಟ್ ಕಡಿಮೆಯಾದರೆ,",
  "print.howOfflineBody": "ಈ ಪುಟದಲ್ಲಿ ಈಗಾಗಲೇ ಇರುವ ಲೇಬಲ್‌ಗಳು ಮತ್ತು ದಾಖಲೆಗಳು ಇನ್ನೂ ಮುದ್ರಿಸುತ್ತವೆ — Print ಬಟನ್, ಲೇಬಲ್‌ಗಳು PDF, Bluetooth ಮತ್ತು USB ಗೆ ಯಾವುದೇ ಸಂಪರ್ಕದ ಅಗತ್ಯವಿಲ್ಲ. ಇಂಟರ್ನೆಟ್ ಅಗತ್ಯವಿರುವುದು ಪುಟ ಮತ್ತು ಅದರ ಉತ್ಪನ್ನಗಳನ್ನು ಮೊದಲಿಗೆ ಲೋಡ್ ಮಾಡುವುದು. ಪೂರ್ಣ ಆಫ್‌ಲೈನ್ ಮೋಡ್ (ಯಾವುದೇ ಸಂಪರ್ಕವಿಲ್ಲದೆ ಅಪ್ಲಿಕೇಶನ್‌ನಲ್ಲಿ ಕೆಲಸ ಮಾಡುವುದು) ಪ್ರತ್ಯೇಕ, ದೊಡ್ಡ ನಿರ್ಮಾಣವಾಗಿದೆ ಮತ್ತು ಇಲ್ಲಿ ಹೇಳಲಾಗಿಲ್ಲ.",
