  "print.footerReceipt": "ಪಾವತಿಯನ್ನು ಹಸ್ತಚಾಲಿತವಾಗಿ ದಾಖಲಿಸಲಾಗುತ್ತದೆ. ಈ ರಸೀದಿಯು ಸ್ವತಃ ಕಾರ್ಡ್‌ಗೆ ಶುಲ್ಕ ವಿಧಿಸುವುದಿಲ್ಲ.",
