  "settings.businesses.createDescription": "ಇದು ತನ್ನದೇ ಆದ ಉತ್ಪನ್ನಗಳು, ಸ್ಥಳಗಳು, ಪೂರೈಕೆದಾರರು ಮತ್ತು ಖರೀದಿ ದಾಖಲೆಗಳೊಂದಿಗೆ ಪ್ರತ್ಯೇಕ ವ್ಯವಹಾರವನ್ನು ರಚಿಸುತ್ತದೆ. ಅಸ್ತಿತ್ವದಲ್ಲಿರುವ ವ್ಯವಹಾರಗಳನ್ನು ಬದಲಾಯಿಸಲಾಗುವುದಿಲ್ಲ. ಪರಿಚಾರಕ ಬಿಡುಗಡೆ-ಪೂರ್ವ ಕಾರ್ಯಕ್ಷೇತ್ರಗಳು ಮತ್ತೊಂದು ಉಚಿತ ಪರೀಕ್ಷೆಯನ್ನು ಪ್ರಾರಂಭಿಸುವುದಿಲ್ಲ.",
  "settings.businesses.createError": "ಈ ವ್ಯವಹಾರವನ್ನು ರಚಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.",
  "settings.businesses.createTitle": "{limit} ರಲ್ಲಿ {number} ವ್ಯವಹಾರವನ್ನು ಸೇರಿಸಿ",
  "settings.businesses.creating": "ರಚಿಸಲಾಗುತ್ತಿದೆ…",
  "settings.businesses.description": "ಪ್ರತಿಯೊಂದು ತನ್ನದೇ ಆದ ಕ್ಯಾಟಲಾಗ್, ಸ್ಥಳಗಳು ಮತ್ತು ಖರೀದಿಯನ್ನು ಇರಿಸುತ್ತದೆ.",
  "settings.businesses.empty": "ಇನ್ನೂ ಯಾವುದೇ ವ್ಯವಹಾರಗಳಿಲ್ಲ — ಇಲ್ಲಿ ಅಥವಾ ಸೈಡ್‌ಬಾರ್ ಸ್ವಿಚರ್‌ನಿಂದ ಒಂದನ್ನು ಸೇರಿಸಿ.",
  "settings.businesses.inUse": "ಬಳಕೆಯಲ್ಲಿದೆ",
  "settings.businesses.limitError": "ನಿಮ್ಮ ಖಾತೆಯು ಅದರ ವ್ಯವಹಾರ ಮಿತಿಯನ್ನು ತಲುಪಿದೆ.",
  "settings.businesses.limitEssentials": "Essentials ಒಂದು ವ್ಯವಹಾರವನ್ನು ಅನುಮತಿಸುತ್ತದೆ. Business ಪ್ರತಿ ಮಾಲೀಕರಿಗೆ ಐದು ವ್ಯವಹಾರಗಳವರೆಗೆ ಅನುಮತಿಸುತ್ತದೆ.",
  "settings.businesses.limitFive": "ನೀವು ಈ ಖಾತೆಗಾಗಿ ಐದು-ವ್ಯವಹಾರ ಮಿತಿಯನ್ನು ತಲುಪಿದ್ದೀರಿ.",
  "settings.businesses.loading": "ನಿಮ್ಮ ವ್ಯವಹಾರಗಳನ್ನು ಲೋಡ್ ಮಾಡಲಾಗುತ್ತಿದೆ…",
  "settings.businesses.loadingPlan": "ನಿಮ್ಮ ಯೋಜನೆಯನ್ನು ಲೋಡ್ ಮಾಡಲಾಗುತ್ತಿದೆ…",
  "settings.businesses.nameError": "ವ್ಯವಹಾರದ ಹೆಸರನ್ನು ನಮೂದಿಸಿ.",
  "settings.businesses.nameLabel": "ವ್ಯವಹಾರದ ಹೆಸರು",
  "settings.businesses.namePlaceholder": "ನಿಮ್ಮ ಎರಡನೇ ವ್ಯವಹಾರ",
  "settings.businesses.noTagline": "ಟ್ಯಾಗ್‌ಲೈನ್ ಇಲ್ಲ",
  "settings.businesses.planLoadError": "ನಿಮ್ಮ ಯೋಜನೆ ಭತ್ಯೆಯನ್ನು ನಾವು ಲೋಡ್ ಮಾಡಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ, ಆದ್ದರಿಂದ ವ್ಯವಹಾರ ಮಿತಿಯನ್ನು ಊಹಿಸುವ ಬದಲು ಮರೆಮಾಡಲಾಗಿದೆ.",
  "settings.businesses.planUnavailable": "ಯೋಜನೆ ಲಭ್ಯವಿಲ್ಲ",
