  "settings.switcher.nameLabel": "ವ್ಯವಹಾರದ ಹೆಸರು",
  "settings.switcher.namePlaceholder": "Harbor & Pine Books",
  "settings.switcher.new": "ಹೊಸದು",
  "settings.switcher.newDescription": "ಪ್ರತಿ ವ್ಯವಹಾರವು ತನ್ನದೇ ಆದ ಉತ್ಪನ್ನಗಳು, ಸ್ಥಳಗಳು, ಪೂರೈಕೆದಾರರು ಮತ್ತು ಖರೀದಿ ಆದೇಶಗಳನ್ನು ಇರಿಸುತ್ತದೆ. ಅವುಗಳ ನಡುವೆ ಏನನ್ನೂ ಹಂಚಿಕೊಳ್ಳಲಾಗುವುದಿಲ್ಲ.",
