  "settings.switcher.taglineLabel": "ಟ್ಯಾಗ್‌ಲೈನ್",
  "settings.switcher.taglinePlaceholder": "ಐಚ್ಛಿಕ",
  "settings.switcher.upgrade": "ಅಪ್‌ಗ್ರೇಡ್ ಮಾಡಿ",
  "settings.title": "ಸೆಟ್ಟಿಂಗ್‌ಗಳು",
  "settings.trial.cancelKeeps": "ನಿಮ್ಮ ಪರೀಕ್ಷೆಯ ಸಮಯದಲ್ಲಿ ರದ್ದುಗೊಳಿಸುವುದರಿಂದ ನಿಮ್ಮ ಪೂರ್ಣ 7 ದಿನಗಳು ಉಳಿಯುತ್ತವೆ — ಪ್ರವೇಶವು {date} ರಂದು ಮುಗಿಯುತ್ತದೆ, ಮತ್ತು ನಿಮಗೆ ಶುಲ್ಕ ವಿಧಿಸಲಾಗುವುದಿಲ್ಲ.",
  "staff.access.noSeatBody": "ಈ ವ್ಯವಹಾರಕ್ಕಾಗಿ ನಿಮ್ಮ ಖಾತೆಗೆ ಯಾವುದೇ ಸಿಬ್ಬಂದಿ ಸ್ಥಾನವಿಲ್ಲ, ಆದ್ದರಿಂದ ಅದರ ದಾಸ್ತಾನು ಮುಚ್ಚಿಯೇ ಉಳಿಯುತ್ತದೆ. Staff & roles ನಲ್ಲಿ ನಿಮ್ಮನ್ನು ಸೇರಿಸಲು ಮಾಲೀಕರನ್ನು ಕೇಳಿ.",
  "staff.access.noSeatTitle": "ಈ ವ್ಯವಹಾರವು ನಿಮ್ಮ ಲಾಗಿನ್‌ಗೆ ತೆರೆದಿಲ್ಲ",
  "staff.access.pendingBody": "ಈ ವ್ಯವಹಾರವು ಸಕ್ರಿಯಗೊಳಿಸದ ನಿಮ್ಮ ಇಮೇಲ್‌ಗಾಗಿ ಆಹ್ವಾನವನ್ನು ಹೊಂದಿದೆ. ನಿಮ್ಮ ಸಿಬ್ಬಂದಿ ಸ್ಥಿತಿಯನ್ನು ಸಕ್ರಿಯವಾಗಿ ಹೊಂದಿಸಲು ಮಾಲೀಕರನ್ನು ಕೇಳಿ. ಅಲ್ಲಿಯವರೆಗೆ ಇಲ್ಲಿ ಏನೂ ಗೋಚರಿಸುವುದಿಲ್ಲ.",
  "staff.access.pendingTitle": "ನಿಮ್ಮ ಆಹ್ವಾನವು ಇನ್ನೂ ಸಕ್ರಿಯವಾಗಿಲ್ಲ",
  "staff.access.signOut": "ಸೈನ್ ಔಟ್",
  "staff.access.suspendedBody": "ನಿರ್ವಾಹಕರು ಸಕ್ರಿಯ ವ್ಯವಹಾರಕ್ಕಾಗಿ ಈ ಸಿಬ್ಬಂದಿ ಖಾತೆಯನ್ನು ಅಮಾನತುಗೊಳಿಸಿದ್ದಾರೆ. ನಿಮ್ಮನ್ನು ಮತ್ತೆ ಸಕ್ರಿಯವಾಗಿ ಹೊಂದಿಸಲು ಅವರನ್ನು ಕೇಳಿ, ನಂತರ ಮತ್ತೆ ಸೈನ್ ಇನ್ ಮಾಡಿ.",
  "staff.access.suspendedTitle": "ನಿಮ್ಮ ಪ್ರವೇಶವನ್ನು ವಿರಾಮಗೊಳಿಸಲಾಗಿದೆ",
  "staff.addFirst": "ಮೊದಲ ಸಿಬ್ಬಂದಿ ಸದಸ್ಯರನ್ನು ಸೇರಿಸಿ",
  "staff.addMember": "ಸಿಬ್ಬಂದಿ ಸದಸ್ಯರನ್ನು ಸೇರಿಸಿ",
  "staff.emptyBody": "ವ್ಯಕ್ತಿಯನ್ನು ಸೇರಿಸಿ, ಅವರಿಗೆ ಪಾತ್ರ ಮತ್ತು ಅದರೊಂದಿಗೆ ಹೋಗುವ ಅನುಮತಿಗಳನ್ನು ನೀಡಿ, ಮತ್ತು ಅವರನ್ನು ಈ ವ್ಯವಹಾರಕ್ಕೆ ಸೈನ್ ಇನ್ ಮಾಡಲು ಇಮೇಲ್ ಮೂಲಕ ಆಹ್ವಾನಿಸಲಾಗುತ್ತದೆ.",
  "staff.emptyTitle": "ಇನ್ನೂ ಯಾವುದೇ ಸಿಬ್ಬಂದಿ ಇಲ್ಲ",
  "staff.eyebrow": "ತಂಡ",
  "staff.how.p1": "ಪ್ರತಿ ಸದಸ್ಯರಿಗೆ ಪಾತ್ರ ಮತ್ತು ಅವರದೇ ಆದ ಅನುಮತಿ ಪಟ್ಟಿ ಇದೆ, ಆದ್ದರಿಂದ ನೀವು ಪಾತ್ರದಿಂದ ಪ್ರಾರಂಭಿಸಬಹುದು ಮತ್ತು ಹೊಸ ಪಾತ್ರವನ್ನು ಮಾಡದೆ ಒಂದನ್ನು ಬದಲಾಯಿಸಬಹುದು. ಪಾತ್ರವನ್ನು ಸಂಪಾದಿಸುವುದರಿಂದ ಈಗಾಗಲೇ ಅದರಲ್ಲಿರುವ ಸದಸ್ಯರನ್ನು ಮರುಬರೆಯಲಾಗುವುದಿಲ್ಲ — ಅವರ ಪಾತ್ರದ ಪೂರ್ವನಿಯೋಜಿತಗಳನ್ನು ಮರು-ಅನ್ವಯಿಸಲು ಸದಸ್ಯರನ್ನು ತೆರೆಯಿರಿ.",
  "staff.how.p2": "ಕಸ್ಟಮ್ ಪಾತ್ರಗಳು Business ವೈಶಿಷ್ಟ್ಯವಾಗಿದೆ: Essentials ಐದು ಅಂತರ್ನಿರ್ಮಿತ ಪಾತ್ರಗಳನ್ನು ಬಳಸುತ್ತದೆ (Owner, Manager, Stock clerk, Sales clerk, Viewer).",
  "staff.how.p3": "ಆಹ್ವಾನಗಳನ್ನು ಇಮೇಲ್ ಮೂಲಕ ಕಳುಹಿಸಲಾಗುತ್ತದೆ. ಸದಸ್ಯರು ಸ್ವೀಕರಿಸಿದ ನಂತರವೇ ಸೈನ್ ಇನ್ ಮಾಡಬಹುದು, ಮತ್ತು ಯಾರನ್ನಾದರೂ ಈ ಪಟ್ಟಿಯಿಂದ ತೆಗೆದುಹಾಕುವುದರಿಂದ ಅವರ ಅಪ್ಲಿಕೇಶನ್ ಖಾತೆಯನ್ನು ಅಳಿಸಲಾಗುವುದಿಲ್ಲ.",
  "staff.how.p4": "ಅಂಗಡಿಯು ವ್ಯಕ್ತಿಯನ್ನು ನಿಯೋಜಿಸಲಾದ ಸ್ಥಳವಾಗಿದೆ. ಅದು ಅವರ ಕಾರ್ಡ್‌ನಲ್ಲಿ ದಾಖಲಾಗಿದೆ; ಅವರು ಏನನ್ನು ತೆರೆಯಬಹುದು ಎಂಬುದನ್ನು ಇನ್ನೂ ಅವರ ಪಾತ್ರ ಮತ್ತು ಅನುಮತಿಗಳಿಂದ ನಿರ್ಧರಿಸಲಾಗುತ್ತದೆ.",
  "staff.how.p5": "ಪ್ರತಿ ವ್ಯಕ್ತಿಯು ಏನನ್ನು ತೆರೆಯಬಹುದು ಎಂದು ಅನುಮತಿಗಳು ನಿರ್ಧರಿಸುತ್ತವೆ: ಅವರ ಪಾತ್ರದ ಹೊರಗಿನ ಮೆನು ವಸ್ತುಗಳನ್ನು ಮರೆಮಾಡಲಾಗುತ್ತದೆ, ಮತ್ತು ನಿರ್ಬಂಧಿಸಿದ ವಿಳಾಸವು ಪುಟದ ಬದಲಾಗಿ “ನಿಮ್ಮ ಪಾತ್ರದಲ್ಲಿ ಇಲ್ಲ” ಸೂಚನೆಯನ್ನು ತೋರಿಸುತ್ತದೆ. ಆ ವ್ಯಕ್ತಿಯು ಮುಂದಿನ ಬಾರಿ ಅಪ್ಲಿಕೇಶನ್ ಅನ್ನು ಲೋಡ್ ಮಾಡಿದಾಗ ಬದಲಾವಣೆ ಅನ್ವಯಿಸುತ್ತದೆ; ಸದಸ್ಯರನ್ನು ಅಮಾನತುಗೊಳಿಸುವುದರಿಂದ ಅವರು ಸಂಪೂರ್ಣವಾಗಿ ಲಾಕ್ ಔಟ್ ಆಗುತ್ತಾರೆ.",
  "staff.how.p6": "ನಿರ್ವಾಹಕರು ಎಲ್ಲಾ ಡೇಟಾವನ್ನು ನೋಡಬಹುದು ಮತ್ತು ಬದಲಾಯಿಸಬಹುದು, ಅಪ್ಲಿಕೇಶನ್ ಬಳಕೆದಾರರು ಮತ್ತು ಪಾತ್ರಗಳನ್ನು ನಿರ್ವಹಿಸಬಹುದು, ಮತ್ತು ಸಿಬ್ಬಂದಿ ಪಾತ್ರದಿಂದ ಎಂದಿಗೂ ಸೀಮಿತವಾಗಿರುವುದಿಲ್ಲ. ಸಿಬ್ಬಂದಿ ದಾಖಲೆ ಇಲ್ಲದ ಯಾರಾದರೂ — ಹೊಸ ವ್ಯವಹಾರದ ಮಾಲೀಕರು — ಪೂರ್ಣ ಪ್ರವೇಶವನ್ನು ಉಳಿಸಿಕೊಳ್ಳುತ್ತಾರೆ.",
  "staff.howTitle": "ಸಿಬ್ಬಂದಿ ಮತ್ತು ಪಾತ್ರಗಳು ಹೇಗೆ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತವೆ",
  "staff.limitBadgeLabel": "ಸಿಬ್ಬಂದಿ",
  "staff.loading": "ಸಿಬ್ಬಂದಿಯನ್ನು ಲೋಡ್ ಮಾಡಲಾಗುತ್ತಿದೆ…",
