  "staff.member.inviteFailedDesc": "ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ, ಅಥವಾ ಈ ಸದಸ್ಯರನ್ನು ತೆಗೆದುಹಾಕಿ ಮತ್ತು ಅವರನ್ನು ಮತ್ತೆ ಸೇರಿಸಿ.",
  "staff.member.inviteResent": "ಆಹ್ವಾನವನ್ನು ಮರುಕಳುಹಿಸಲಾಗಿದೆ",
  "staff.member.inviteResentDesc": "{email} ಅನ್ನು {role} ಆಗಿ ಮತ್ತೆ ಆಹ್ವಾನಿಸಲಾಗಿದೆ. ಅವರು ಸೈನ್ ಇನ್ ಮಾಡಿದ ನಂತರ ಅವರ ಸ್ಥಿತಿಯನ್ನು Active ಎಂದು ಹೊಂದಿಸಿ.",
  "staff.member.noRole": "ಪಾತ್ರವಿಲ್ಲ",
  "staff.member.noStore": "ಅಂಗಡಿಯಿಲ್ಲ",
  "staff.member.permissions": "ಅನುಮತಿಗಳು",
  "staff.member.remove": "ತೆಗೆದುಹಾಕಿ",
  "staff.member.removeConfirm": "{name} ಅನ್ನು ಸಿಬ್ಬಂದಿ ಪಟ್ಟಿಯಿಂದ ತೆಗೆದುಹಾಕುವುದೇ? ಅವರ ಅಪ್ಲಿಕೇಶನ್ ಖಾತೆ ಉಳಿಯುತ್ತದೆ.",
  "staff.member.removed": "ಸಿಬ್ಬಂದಿ ಸದಸ್ಯರನ್ನು ತೆಗೆದುಹಾಕಲಾಗಿದೆ",
  "staff.member.resendInvite": "ಆಹ್ವಾನವನ್ನು ಮರುಕಳುಹಿಸಿ",
