  "staff.member.sending": "ಕಳುಹಿಸಲಾಗುತ್ತಿದೆ…",
  "staff.memberDialog.accessLabel": "ಕಾರ್ಯಕ್ಷೇತ್ರ ಪ್ರವೇಶ",
  "staff.memberDialog.addButton": "ಸಿಬ್ಬಂದಿ ಸದಸ್ಯರನ್ನು ಸೇರಿಸಿ",
  "staff.memberDialog.addDescription": "ಪ್ರಾರಂಭಿಸಲು ಪಾತ್ರವನ್ನು ಆರಿಸಿ, ನಂತರ ಅವರು ತಲುಪಬೇಕಾದ ಅಥವಾ ತಲುಪಬಾರದ ಯಾವುದನ್ನಾದರೂ ಹೊಂದಿಸಿ.",
  "staff.memberDialog.addTitle": "ಸಿಬ್ಬಂದಿ ಸದಸ್ಯರನ್ನು ಸೇರಿಸಿ",
