  "staff.memberDialog.adminHint": "ನಿರ್ವಾಹಕರು ಎಲ್ಲಾ ಡೇಟಾವನ್ನು ನೋಡಬಹುದು ಮತ್ತು ಬದಲಾಯಿಸಬಹುದು ಮತ್ತು ಅಪ್ಲಿಕೇಶನ್ ಬಳಕೆದಾರರನ್ನು ನಿರ್ವಹಿಸಬಹುದು.",
